"""Cobertura del universo previo y de la cohorte; reutiliza CSV sin nuevas rutas."""
from pathlib import Path
import argparse,hashlib,json
import pandas as pd

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--base',type=Path,default=Path('etapa1_terrestre_citra'));ap.add_argument('--salida',type=Path,default=Path('etapa1_terrestre_citra/cierre_final/cobertura'));args=ap.parse_args();b=args.base;p=b/'resultados/entrega_02/csv';out=args.salida;out.mkdir(parents=True,exist_ok=True)
 def load(path):return pd.read_csv(path,encoding='utf-8-sig',keep_default_na=False)
 x=load(b/'insumos_decisiones/alcance_y_clasificacion_anteriores.csv');a=load(p/'auditoria_112.csv');h=load(p/'homologacion_cerrada_registros.csv');d=load(p/'matriz_auxiliar_corredor_detallada.csv');z=load(p/'matriz_auxiliar_corredor_zonas.csv')
 assert x.id_encuesta.nunique()==len(x)==8828;assert a.id_encuesta.nunique()==len(a)==112;assert h.id_encuesta.nunique()==8828
 cohort=x[x.estado_filtro.eq('Incluido')&x.ruta_utilizada.eq('Tierra confirmada')];assert set(cohort.id_encuesta)==set(a.id_encuesta)
 merged=a.merge(h[['id_encuesta','hash_registro_original']],on='id_encuesta',validate='one_to_one',suffixes=('_auditoria','_capa'));assert merged.hash_registro_original_auditoria.eq(merged.hash_registro_original_capa).all()
 for side in ['origen','destino']:
  compared=a.merge(h[['id_encuesta',f'{side}_lat_original',f'{side}_lon_original']],on='id_encuesta',validate='one_to_one',suffixes=('_auditoria','_capa'))
  for coord in ['lat','lon']:assert compared[f'{side}_{coord}_original_auditoria'].astype(str).eq(compared[f'{side}_{coord}_original_capa'].astype(str)).all()
 blocks=x.groupby(['estado_filtro','ruta_utilizada'],dropna=False).size().rename('entrevistas').reset_index();blocks['interpretacion']='Clasificacion historica de alcance/ruta; no flujo ni confirmacion nueva';blocks.to_csv(out/'universo_y_alcance_previo.csv',index=False,encoding='utf-8-sig')
 pending=x[x.estado_filtro.eq('Incluido')&~x.id_encuesta.isin(a.id_encuesta)].copy();pending['estado_cierre']='Fuera de cohorte112; no homologar a cero ni clasificar ruta de nuevo sin evidencia';pending.to_csv(out/'incluidas_fuera_cohorte_112.csv',index=False,encoding='utf-8-sig')
 detailcols=['origen_detallado','destino_detallado','zona_origen','zona_destino','campana','segmento','control','sentido_observado'];coverage=a.groupby(detailcols,dropna=False).agg(entrevistas=('id_encuesta','size'),OD_homologado=('OD_homologado',lambda y:sum(str(v)=='True' for v in y)),con_factor=('factor_expansion',lambda y:sum(str(v)!='' for v in y))).reset_index();coverage.to_csv(out/'cobertura_OD_control.csv',index=False,encoding='utf-8-sig')
 assert not a.ruta_observada_directamente.astype(str).eq('True').any()
 incomplete=a[~a.OD_homologado.astype(str).eq('True')];incomplete[['id_encuesta','origen_original','destino_original','zona_origen','zona_destino','motivo_principal']].to_csv(out/'OD_no_completados.csv',index=False,encoding='utf-8-sig')
 # Referencia ARISTO anterior existente: solo lectura y recuento, sin nueva estimacion.
 arp=Path('demanda_lago_github/outputs/matrices_od_referencia/matriz_od_terrestre.csv');ar=load(arp);arf=pd.to_numeric(ar.demanda_expandida_viajes_diarios_promedio,errors='coerce').notna();aristo={'fuente_existente':str(arp),'sha256':hashlib.sha256(arp.read_bytes()).hexdigest(),'filas_estructura':len(ar),'filas_flujo_existente':int(arf.sum()),'entrevistas_OD_en_filas_con_flujo':int(pd.to_numeric(ar.loc[arf,'encuestas_validas']).sum()),'horas_ventana':sorted(pd.to_numeric(ar.loc[arf,'cobertura_horas_dia']).unique()),'control':'ODC-3 Cerro Castillo','evidencia':'Declaracion expresa sin transbordador ni frontera segun grado_evidencia, pasos_fronterizos y procedimiento del CSV existente','limitaciones':'Referencia terrestre parcial; un control; pocas observaciones OD comparables; no24h; noinvierno; no permite completar el terrestre total. No se sumo a CITRA ni se implemento alternativa.'}
 findings={'estado':'correcto','pruebas':{'universo_8828_unicas':True,'cohorte_112_exacta_y_sin_duplicacion':True,'cohorte_subconjunto_295_incluidas':True,'hash_y_coordenadas_112_identicos_capa_cerrada':True,'ninguna_ruta_completa_declarada_en_cohorte':True},'universo_original':8828,'incluidas_alcance_previo':int(x.estado_filtro.eq('Incluido').sum()),'cohorte_reauditada':112,'incluidas_fuera_cohorte':len(pending),'rutas_previas_fuera_cohorte':pending.ruta_utilizada.value_counts().to_dict(),'porcentaje_entrevistas_incluidas_reauditadas_NO_cuota_demanda':112/int(x.estado_filtro.eq('Incluido').sum())*100,'OD_incompletos_cohorte':len(incomplete),'entrevistas_compatibles_corredor_previo':int(a.aceptada_corredor_auxiliar.astype(str).eq('True').sum()),'localidades_OD_cohorte':len(a[['origen_detallado','destino_detallado']].drop_duplicates()),'pares_localidad_auxiliar':len(d[['origen','destino']].drop_duplicates()),'pares_zonales_auxiliar':len(z[['zona_origen','zona_destino']].drop_duplicates()),'celdas_detalladas_auxiliar_campana_clase':len(d),'celdas_detalladas_con_flujo_previo':int(pd.to_numeric(d.flujo_corredor_auxiliar_12h,errors='coerce').notna().sum()),'celdas_detalladas_flujo_faltante_previo':int(pd.to_numeric(d.flujo_corredor_auxiliar_12h,errors='coerce').isna().sum()),'celdas_zonales_auxiliar_campana_clase':len(z),'cobertura_no_observada':['Los183incluidos anteriores con ruta probable/desconocida no se transforman en alta confianza ni en ceros: no fueron esta cohorte.','La muestra112 no es censo del mercado ni cantidad total de vehiculos.','Ausencia de OD en la muestra no indica cero estructural de demanda.','Aforos y OD solo en jornadas08–20 compatibles de verano/otoño; sin noche, invierno, anualizacion ni estacionalidad.','SoloVL/CAM; no estima pasajeros o peatones ni sustituye demanda lacustre.','Localidades originales se conservan; zonas no resuelven accesos intrazonales exactos.','La matriz no cubre todo flujo regional ni todo el mercado beneficiable por el cruce.','Comparaciones entre controles en distintas fechas incluyen variacion temporal y error de muestra; no son prueba directa de inconsistencia o adicionalidad.'],'viabilidad_propuesta':'B — Utilizable parcialmente','justificacion':'Existen aforos EOD compatibles y fracciones OD expandibles, pero la cobertura de alcance/ruta, temporal y de muestreo impide una demanda terrestre total. La ausencia de itinerario exacto no vuelve inutilizable al corredor observado.','recomendacion':'Utilizar CITRA como referencia parcial del corredor, separada por categorias de confianza y exposicion; ARISTO lacustre como bloque independiente. No sumar fuentes o pantallas, no completar faltantes por logit ni por comuna. Cerrar revision manual y seguir a etapas posteriores con limites explicitos.','aristo_terrestre_existente':aristo,'fuentes_cache_sha256':{str(path):hashlib.sha256(path.read_bytes()).hexdigest() for path in [p/'auditoria_112.csv',p/'homologacion_cerrada_registros.csv',p/'matriz_auxiliar_corredor_detallada.csv',p/'matriz_auxiliar_corredor_zonas.csv',b/'insumos_decisiones/alcance_y_clasificacion_anteriores.csv']}}
 (out/'resumen_cobertura.json').write_text(json.dumps(findings,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({k:v for k,v in findings.items() if k not in ['fuentes_cache_sha256','aristo_terrestre_existente','cobertura_no_observada']},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
